/**
 * src/data/libraryManifest.js
 *
 * Runtime hooks for public/library/manifest.json.
 * The manifest is generated by: node scripts/organizeLibrary.js
 *
 * Hooks:
 *   useLibraryManifest()        – full manifest + loading/error state
 *   useCategory(categoryId)     – files for one category
 *   useFileSearch(query)        – cross-category full-text search
 *
 * Cart compatibility:
 *   Every file entry has: { id, filename, path, type, category, sizeBytes, title }
 *   — exactly the shape CartContext expects.
 */

import { useState, useEffect, useMemo } from 'react';

// ─── Module-level cache (single fetch per browser session) ────────────────────

let _promise = null;
let _cache   = null;

function fetchManifest() {
    if (_cache)   return Promise.resolve(_cache);
    if (_promise) return _promise;

    _promise = fetch('/library/manifest.json')
        .then((r) => {
            if (!r.ok) throw new Error(`manifest HTTP ${r.status}`);
            return r.json();
        })
        .then((data) => {
            _cache   = data;
            _promise = null;
            return data;
        })
        .catch((err) => {
            _promise = null; // allow retry
            throw err;
        });

    return _promise;
}

// ─── useLibraryManifest ───────────────────────────────────────────────────────

export function useLibraryManifest() {
    const [state, setState] = useState({
        data:    _cache,
        loading: !_cache,
        error:   null,
    });

    useEffect(() => {
        if (_cache) return;
        let cancelled = false;

        fetchManifest()
            .then((data) => {
                if (!cancelled) setState({ data, loading: false, error: null });
            })
            .catch((err) => {
                if (!cancelled) setState({ data: null, loading: false, error: err.message });
            });

        return () => { cancelled = true; };
    }, []);

    return state;
}

// ─── useCategory ──────────────────────────────────────────────────────────────

export function useCategory(categoryId) {
    const { data, loading, error } = useLibraryManifest();

    const files = useMemo(() => {
        if (!data || !categoryId) return [];
        return data.files.filter((f) => f.category === categoryId);
    }, [data, categoryId]);

    const meta = useMemo(() => {
        if (!data) return null;
        return data.categories[categoryId] || null;
    }, [data, categoryId]);

    return { files, meta, loading, error };
}

// ─── useFileSearch ────────────────────────────────────────────────────────────

export function useFileSearch(query) {
    const { data, loading, error } = useLibraryManifest();

    const results = useMemo(() => {
        if (!data || !query || query.trim().length < 2) return [];
        const q = query.toLowerCase().trim();
        return data.files.filter((f) =>
            f.filename.toLowerCase().includes(q) ||
            f.title.toLowerCase().includes(q) ||
            f.category.toLowerCase().includes(q)
        );
    }, [data, query]);

    return { results, loading, error };
}

